var setPrinterAgent = defineCommand({
  type: "SetPrinterAgent",
  schema: setPrinterAgentSchema,
  right: "admin",
  needsOrder: false,
  allowWhenDayClosed: true,
  apply(ctx, p) {
    if (!ctx.db.prepare("SELECT 1 FROM printer WHERE id = ?").get(p.printerId)) throw new PosError("NOT_FOUND", "Printer not found.", { printerId: p.printerId });
    if (p.agentId) {
      const a = ctx.db.prepare("SELECT revoked_at FROM print_agent WHERE id = ?").get(p.agentId);
      if (!a) throw new PosError("NOT_FOUND", "Print agent not found.", { agentId: p.agentId });
      if (a.revoked_at) throw new PosError("INVALID_STATE", "This print agent was removed. Add a new one.");
    }
    const before = ctx.db.prepare("SELECT agent_id FROM printer_agent WHERE printer_id = ?").pluck().get(p.printerId) ?? null;
    if (p.agentId) ctx.db.prepare("INSERT INTO printer_agent (printer_id, agent_id) VALUES (?, ?) ON CONFLICT(printer_id) DO UPDATE SET agent_id = excluded.agent_id").run(p.printerId, p.agentId);
    else ctx.db.prepare("DELETE FROM printer_agent WHERE printer_id = ?").run(p.printerId);
    ctx.audit({ entity: "printer", entityId: p.printerId, action: "printer.agent", before: { agentId: before }, after: { agentId: p.agentId } });
    ctx.emit("printers", "printer.changed", { printerId: p.printerId });
    return { result: { agentId: p.agentId } };
  }
});

// src/commands/reservation-support.ts
var MIN = 6e4;
function localTime(iso, timeZone) {
  return new Intl.DateTimeFormat("en-IN", { hour: "2-digit", minute: "2-digit", hour12: false, timeZone }).format(new Date(iso));
}
function holdingBooking(db, tableId, now, exceptReservationId) {
  const config2 = getConfig(db);
  const rows = db.prepare(
    `SELECT r.* FROM reservation r JOIN reservation_table rt ON rt.reservation_id = r.id
       WHERE rt.table_id = ? AND r.status = 'booked' ORDER BY r.starts_at`
  ).all(tableId);
  const t = now.getTime();
  return rows.find((r) => {
    if (r.id === exceptReservationId) return false;
    const start = Date.parse(r.starts_at);
    return t >= start - config2["reservation.holdMin"] * MIN && t < start + config2["reservation.graceMin"] * MIN;
  }) ?? null;
}
function refuseIfHeld(ctx, table, exceptReservationId) {
  const r = holdingBooking(ctx.db, table.id, ctx.now, exceptReservationId);
  if (!r) return;
  throw new PosError("INVALID_STATE", `Table ${table.label} is held for ${r.guest_name} (${r.party_size}) at ${localTime(r.starts_at, ctx.timeZone)}.`, {
    reason: "reserved",
    reservationId: r.id,
    tableId: table.id
  });
}
function refuseClashes(ctx, tableIds, startsAt, durationMin, exceptReservationId) {
  const start = Date.parse(startsAt);
  const end = start + durationMin * MIN;
  for (const tableId of tableIds) {
    const others = ctx.db.prepare(
      `SELECT r.id, r.guest_name, r.starts_at, r.duration_min, t.label FROM reservation r
         JOIN reservation_table rt ON rt.reservation_id = r.id JOIN dining_table t ON t.id = rt.table_id
         WHERE rt.table_id = ? AND r.status = 'booked' AND r.id <> coalesce(?, '')`
    ).all(tableId, exceptReservationId);
    for (const o of others) {
      const oStart = Date.parse(o.starts_at);
      if (start < oStart + o.duration_min * MIN && oStart < end) {
        throw new PosError(
          "INVALID_STATE",
          `Table ${o.label} is already booked for ${o.guest_name} ${localTime(o.starts_at, ctx.timeZone)}\u2013${localTime(new Date(oStart + o.duration_min * MIN).toISOString(), ctx.timeZone)}.`,
          { reason: "clash", reservationId: o.id, tableId }
        );
      }
    }
  }
}
function requireBookableTables(ctx, tableIds) {
  for (const id of tableIds) {
    const t = ctx.db.prepare("SELECT label, status FROM dining_table WHERE id = ?").get(id);
    if (!t) throw new PosError("NOT_FOUND", "Table not found.", { tableId: id });
    if (t.status === "blocked") throw new PosError("INVALID_STATE", `Table ${t.label} is blocked.`, { tableId: id });
  }
}
function requireReservation(ctx, id) {
  const r = ctx.db.prepare("SELECT * FROM reservation WHERE id = ?").get(id);
  if (!r) throw new PosError("NOT_FOUND", "Booking not found.", { reservationId: id });
  return r;
}
function requireBooked(r) {
  if (r.status !== "booked") throw new PosError("INVALID_STATE", `This booking is ${r.status.replace("_", "-")}.`, { status: r.status });
}
var tablesOf = (db, reservationId) => db.prepare("SELECT table_id FROM reservation_table WHERE reservation_id = ? ORDER BY rowid").pluck().all(reservationId);
function bookingsChanged(ctx, data) {
  ctx.emit(["floor", "reservations"], "reservations.changed", data);
}

