// src/commands/captain-support.ts
function requireActiveUser(db, userId) {
  const u = db.prepare("SELECT id, name FROM app_user WHERE id = ? AND active = 1").get(userId);
  if (!u) throw new PosError("NOT_FOUND", "That person is not on the active staff list.", { userId });
  return u;
}
function sectionCaptains(db, tableId) {
  return db.prepare(
    `SELECT DISTINCT s.user_id FROM captain_section s JOIN app_user u ON u.id = s.user_id AND u.active = 1
         WHERE s.table_id = @tableId OR s.area_id = (SELECT area_id FROM dining_table WHERE id = @tableId)
         ORDER BY s.user_id`
  ).pluck().all({ tableId });
}
function defaultCaptain(db, tableId) {
  const byTable = db.prepare("SELECT DISTINCT s.user_id FROM captain_section s JOIN app_user u ON u.id = s.user_id AND u.active = 1 WHERE s.table_id = ?").pluck().all(tableId);
  if (byTable.length) return byTable.length === 1 ? byTable[0] : null;
  const byArea = sectionCaptains(db, tableId);
  return byArea.length === 1 ? byArea[0] : null;
}

// src/commands/assign-captain.ts
