// src/commands/create-reservation.ts
var PAST_GRACE_MS = 10 * 6e4;
var createReservation = defineCommand({
  type: "CreateReservation",
  schema: createReservationSchema,
  right: "reservation.manage",
  needsOrder: false,
  apply(ctx, p) {
    const startsAt = new Date(p.startsAt).toISOString();
    if (Date.parse(startsAt) < ctx.now.getTime() - PAST_GRACE_MS) throw new PosError("VALIDATION", "That time has already passed.", { field: "startsAt" });
    const id = p.id ?? newId();
    if (ctx.db.prepare("SELECT 1 FROM reservation WHERE id = ?").get(id)) throw new PosError("INVALID_STATE", "That booking id is already in use.", { id });
    requireBookableTables(ctx, p.tableIds);
    refuseClashes(ctx, p.tableIds, startsAt, p.durationMin, null);
    ctx.db.prepare(
      `INSERT INTO reservation (id, guest_name, phone, party_size, starts_at, duration_min, note, status, created_at, created_by)
         VALUES (?, ?, ?, ?, ?, ?, ?, 'booked', ?, ?)`
    ).run(id, p.guestName, p.phone, p.partySize, startsAt, p.durationMin, p.note, ctx.nowIso, ctx.actor.userId);
    const link = ctx.db.prepare("INSERT INTO reservation_table (reservation_id, table_id) VALUES (?, ?)");
    for (const t of p.tableIds) link.run(id, t);
    ctx.audit({
      entity: "reservation",
      entityId: id,
      action: "reservation.create",
      after: { guestName: p.guestName, partySize: p.partySize, startsAt, durationMin: p.durationMin, tableIds: p.tableIds }
    });
    bookingsChanged(ctx, { reservationId: id });
    return { result: { reservationId: id } };
  }
});

// src/commands/day-end.ts
var KEEP_PROCESSED_DAYS = 7;
var KEEP_EVENTS = 1e4;
var KEEP_PRINT_BYTES_DAYS = 30;
function buildZReport(db, businessDate, cashCountedPaise, outletName, closedAt) {
  const totals = db.prepare(
    `SELECT count(*) AS bills, COALESCE(sum(b.subtotal_paise), 0) AS gross, COALESCE(sum(b.discount_paise), 0) AS discount,
              COALESCE(sum(b.service_charge_paise), 0) AS sc, COALESCE(sum(b.cgst_paise), 0) AS cgst, COALESCE(sum(b.sgst_paise), 0) AS sgst,
              COALESCE(sum(b.igst_paise), 0) AS igst, COALESCE(sum(b.round_off_paise), 0) AS ro, COALESCE(sum(b.total_paise), 0) AS net
       FROM bill b JOIN "order" o ON o.id = b.order_id WHERE o.business_date = ? AND b.state = 'settled'`
  ).get(businessDate);
  const byMode = db.prepare(
    `SELECT p.mode, sum(p.amount_paise) AS amountPaise FROM payment p JOIN bill b ON b.id = p.bill_id JOIN "order" o ON o.id = b.order_id
       WHERE o.business_date = ? AND b.state = 'settled' GROUP BY p.mode ORDER BY p.mode`
  ).all(businessDate);
  const byArea = db.prepare(
    `SELECT COALESCE(a.name, 'Takeaway') AS name, count(*) AS bills, sum(b.total_paise) AS amountPaise
       FROM bill b JOIN "order" o ON o.id = b.order_id LEFT JOIN dining_table t ON t.id = o.table_id LEFT JOIN area a ON a.id = t.area_id
       WHERE o.business_date = ? AND b.state = 'settled' GROUP BY 1 ORDER BY 1`
  ).all(businessDate);
  const lines = db.prepare(
    `SELECT oi.id, oi.qty, oi.unit_price_paise, oi.tax_rate_bp, COALESCE(c.name, 'Other') AS category
       FROM order_item oi JOIN "order" o ON o.id = oi.order_id LEFT JOIN menu_item mi ON mi.id = oi.item_id LEFT JOIN category c ON c.id = mi.category_id
       WHERE o.business_date = ? AND o.state = 'settled' AND oi.status = 'fired'`
  ).all(businessDate);
  const addonsOf = db.prepare("SELECT qty, price_paise AS pricePaise FROM order_item_addon WHERE order_item_id = ?");
  const cats = /* @__PURE__ */ new Map();
  for (const l of lines) {
    const amount = lineAmount({ id: l.id, qty: l.qty, unitPricePaise: l.unit_price_paise, taxRateBp: l.tax_rate_bp, addons: addonsOf.all(l.id) });
    const c = cats.get(l.category) ?? { qty: 0, amountPaise: 0 };
    cats.set(l.category, { qty: c.qty + l.qty, amountPaise: c.amountPaise + amount });
  }
  const one = (sql) => db.prepare(sql).pluck().get(businessDate) ?? 0;
  const cashPayments = byMode.find((m) => m.mode === "cash")?.amountPaise ?? 0;
  const payIn2 = one(`SELECT sum(amount_paise) FROM cash_movement WHERE business_date = ? AND kind IN ('opening', 'pay_in')`);
  const payOut2 = one(`SELECT sum(amount_paise) FROM cash_movement WHERE business_date = ? AND kind = 'pay_out'`);
  return {
    outletName,
    businessDate,
    closedAt,
    bills: totals.bills,
    covers: one(`SELECT sum(covers) FROM "order" WHERE business_date = ? AND state = 'settled'`),
    kots: one(`SELECT count(*) FROM kot WHERE business_date = ?`),
    grossSalesPaise: totals.gross,
    discountPaise: totals.discount,
    serviceChargePaise: totals.sc,
    cgstPaise: totals.cgst,
    sgstPaise: totals.sgst,
    igstPaise: totals.igst,
    roundOffPaise: totals.ro,
    netSalesPaise: totals.net,
    byMode,
    byArea,
    byCategory: [...cats.entries()].map(([name4, c]) => ({ name: name4, ...c })).sort((a, b) => b.amountPaise - a.amountPaise),
    cancelledAfterFire: one(`SELECT count(*) FROM order_item oi JOIN "order" o ON o.id = oi.order_id WHERE o.business_date = ? AND oi.status = 'cancelled' AND oi.kot_id IS NOT NULL`),
    cashExpectedPaise: cashPayments + payIn2 - payOut2,
    cashCountedPaise,
    voids: db.prepare(
      `SELECT (SELECT d.bill_no_text FROM bill_document d WHERE d.bill_id = b.id ORDER BY d.revision DESC LIMIT 1) AS billNo, b.total_paise AS amountPaise,
                (SELECT a.reason FROM audit_event a WHERE a.entity_id = b.id AND a.action = 'bill.void' ORDER BY a.seq DESC LIMIT 1) AS reason
         FROM bill b JOIN "order" o ON o.id = b.order_id WHERE o.business_date = ? AND b.state = 'void' AND b.bill_no IS NOT NULL ORDER BY b.fy, b.bill_no`
    ).all(businessDate),
    payInPaise: one(`SELECT sum(amount_paise) FROM cash_movement WHERE business_date = ? AND kind = 'pay_in'`),
    payOutPaise: payOut2
  };
}
var dayEnd = defineCommand({
  type: "DayEnd",
  schema: dayEndSchema,
  right: "dayend",
  needsOrder: false,
  apply(ctx, p) {
    const { db } = ctx;
    const open2 = db.prepare(`SELECT o.id, COALESCE(t.label, 'Takeaway') AS label FROM "order" o LEFT JOIN dining_table t ON t.id = o.table_id WHERE o.state IN ('open', 'billed') ORDER BY 2`).all();
    if (open2.length > 0) {
      throw new PosError("INVALID_STATE", `${open2.length} order${open2.length > 1 ? "s are" : " is"} still open (${open2.map((o) => o.label).join(", ")}). Settle them first.`, {
        openOrders: open2
      });
    }
    const cfg = getConfig(db);
    const when = printedDateTime(ctx.now, ctx.timeZone);
    const z2 = buildZReport(db, ctx.businessDate, p.cashCountedPaise, cfg["outlet.name"], `${when.date} ${when.time}`);
    db.prepare("UPDATE business_day SET closed_at = ?, closed_by = ?, z_report_json = ? WHERE date = ? AND closed_at IS NULL").run(
      ctx.nowIso,
      ctx.actor.userId,
      JSON.stringify(z2),
      ctx.businessDate
    );
    db.prepare(`INSERT INTO cash_movement (id, business_date, kind, amount_paise, reason, user_id, at) VALUES (?, ?, 'closing', ?, 'day end count', ?, ?)`).run(
      ctx.commandId,
      ctx.businessDate,
      p.cashCountedPaise,
      ctx.actor.userId,
      ctx.nowIso
    );
    const licence = ctx.licence.status(db, ctx.now);
    const next = licence.canOpenDay ? openNextBusinessDay(db, ctx.timeZone, ctx.now, `day end of ${ctx.businessDate}`) : null;
    const printer = billPrinter(db, cfg);
    if (printer) {
      const { bytes, preview } = renderZReport(z2, { paper: printer.paper });
      ctx.print({ printerId: printer.id, docKind: "zreport", refId: ctx.businessDate, bytes, previewText: preview });
    }
    const cutoff = new Date(ctx.now.getTime() - KEEP_PROCESSED_DAYS * 864e5).toISOString();
    db.prepare("DELETE FROM processed_command WHERE at < ?").run(cutoff);
    db.prepare("DELETE FROM event_log WHERE seq <= (SELECT max(seq) FROM event_log) - ?").run(KEEP_EVENTS);
    const printCutoff = new Date(ctx.now.getTime() - KEEP_PRINT_BYTES_DAYS * 864e5).toISOString();
    db.prepare("UPDATE print_job SET bytes = x'', preview_text = NULL WHERE state IN ('done', 'failed') AND created_at < ? AND length(bytes) > 0").run(printCutoff);
    ctx.audit({
      entity: "business_day",
      entityId: ctx.businessDate,
      action: "day.close",
      after: { netSalesPaise: z2.netSalesPaise, bills: z2.bills, cashExpectedPaise: z2.cashExpectedPaise, cashCountedPaise: p.cashCountedPaise, nextDate: next },
      leakage: p.cashCountedPaise !== z2.cashExpectedPaise
    });
    ctx.emit("system", "day.changed", { businessDate: next, closedDate: ctx.businessDate });
    ctx.outbox("day.closed", { businessDate: ctx.businessDate, zReport: z2 });
    return { result: { closedDate: ctx.businessDate, nextDate: next, zReport: z2, printerId: printer?.id ?? null, ...next ? {} : { licence: licence.message } } };
  }
});

// src/commands/import-menu.ts
var importMenu = defineCommand({
  type: "ImportMenu",
  schema: importMenuSchema,
  right: "admin",
  needsOrder: false,
  allowWhenDayClosed: true,
  apply(ctx, p) {
    const { db } = ctx;
    const nameTaken = db.prepare("SELECT 1 FROM menu_item WHERE name = ? COLLATE NOCASE AND active = 1");
    const codeTaken = db.prepare("SELECT name FROM menu_item WHERE short_code = ?").pluck();
    const problems = [];
    const names = /* @__PURE__ */ new Set();
    const codes = /* @__PURE__ */ new Set();
    p.items.forEach((it, i) => {
      const item = i + 1;
      if (names.has(it.name.toLowerCase())) problems.push({ item, message: `"${it.name}" appears twice.` });
      names.add(it.name.toLowerCase());
      if (nameTaken.get(it.name)) problems.push({ item, message: `"${it.name}" is already on the menu.` });
      if (it.shortCode) {
        const owner = codeTaken.get(it.shortCode);
        if (owner !== void 0) problems.push({ item, message: `Code ${it.shortCode} is already used by ${owner}.` });
        else if (codes.has(it.shortCode)) problems.push({ item, message: `Code ${it.shortCode} appears twice.` });
        codes.add(it.shortCode);
      }
    });
    if (problems.length) {
      throw new PosError("VALIDATION", `${problems.length} problem(s) found. Nothing was imported.`, { problems: problems.slice(0, 100) });
    }
    const categories2 = new Map(
      db.prepare("SELECT id, name FROM category ORDER BY sort, rowid").all().map((c) => [categoryKey(c.name), c.id])
    );
    let sort2 = db.prepare("SELECT coalesce(max(sort), 0) FROM category").pluck().get() + 10;
    const newCategory = db.prepare("INSERT INTO category (id, name, sort) VALUES (?, ?, ?)");
    const newItem = db.prepare(
      `INSERT INTO menu_item (id, category_id, name, short_code, veg, base_price_paise, tax_rate_bp, hsn_sac) VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
    );
    const createdCategories = [];
    const itemIds = [];
    for (const it of p.items) {
      const key = categoryKey(it.category);
      let categoryId = categories2.get(key);
      if (!categoryId) {
        categoryId = newId();
        newCategory.run(categoryId, it.category.trim().replace(/\s+/g, " "), sort2);
        sort2 += 10;
        categories2.set(key, categoryId);
        createdCategories.push(it.category);
      }
      const id = newId();
      newItem.run(id, categoryId, it.name, it.shortCode, it.veg ? 1 : 0, it.pricePaise, it.taxRateBp, it.hsnSac);
      itemIds.push(id);
    }
    ctx.audit({ entity: "menu", entityId: p.importId, action: "menu.import", after: { items: p.items.length, createdCategories } });
    menuChanged(ctx, itemIds);
    return { result: { imported: itemIds.length, categoriesCreated: createdCategories.length } };
  }
});

// src/licence/install.ts
function checkedKey(ctx, key) {
  if (!ctx.licence.enforced) throw new PosError("INVALID_STATE", "Licences are not checked in a development run.");
  const verified = ctx.licence.verify(key);
  if (!verified.ok) throw new PosError("VALIDATION", verified.reason, { field: "key" });
  const status = licenceStatus(verified, ctx.now, ctx.licence.hardwareId);
  if (!status.canOpenDay) throw new PosError("VALIDATION", `This key ended on ${verified.payload.expiresAt.slice(0, 10)}. Ask for a renewed key.`, { field: "key" });
  return { payload: verified.payload, state: status.state };
}
function storeLicenceKey(ctx, key, checked, action) {
  const before = ctx.db.prepare("SELECT licence_key FROM licence WHERE id = 1").pluck().get();
  ctx.db.prepare("UPDATE licence SET licence_key = ?, installed_at = ?, installed_by = ? WHERE id = 1").run(key.replace(/\s+/g, ""), ctx.nowIso, ctx.actor.userId);
  const { licensee, expiresAt, seats, hardwareId: hardwareId2 } = checked.payload;
  ctx.audit({ entity: "licence", entityId: "licence", action, before: { hadKey: before !== null }, after: { licensee, expiresAt, seats, hardwareId: hardwareId2 } });
  let opened = null;
  if (!currentBusinessDate(ctx.db)) {
    opened = openNextBusinessDay(ctx.db, ctx.timeZone, ctx.now, action === "licence.renew" ? "licence renewed" : "licence installed");
    ctx.emit("system", "day.changed", { businessDate: opened, closedDate: null });
  }
  ctx.emit("system", "licence.changed", { state: checked.state });
  return { licensee, expiresAt, seats, state: checked.state, openedBusinessDate: opened };
}

