// src/auth/devices.ts
import { createHash as createHash8, randomBytes as randomBytes4, randomInt } from "node:crypto";
var MASTER_DEVICE_ID = UNPAIRED_DEVICE_ID;
var PAIRING_MINUTES = 10;
var MAX_PENDING = 20;
var deviceTokenHash = (token) => createHash8("sha256").update(`device:${token}`).digest("hex");
function isLoopback(ip) {
  return ip === "127.0.0.1" || ip === "::1" || ip === "::ffff:127.0.0.1";
}
function deviceTokenOf(authorization) {
  const m = /^Device ([A-Za-z0-9_-]{20,100})$/.exec(authorization?.trim() ?? "");
  return m?.[1];
}
function resolveDevice(db, token) {
  if (!token) return null;
  return db.prepare("SELECT id, name, kind FROM device WHERE token_hash = ? AND revoked_at IS NULL").get(deviceTokenHash(token)) ?? null;
}
function deviceUnpaired() {
  return new PosError("UNAUTHENTICATED", "This device is not paired with the outlet server. Pair it first.", { reason: "device_not_paired" });
}
function expireOld(db, at) {
  db.prepare(`UPDATE pairing_request SET status = 'expired' WHERE status = 'pending' AND expires_at <= ?`).run(at);
}
function createPairingRequest(db, input2, remoteAddr, now) {
  const at = now.toISOString();
  return db.transaction(() => {
    expireOld(db, at);
    const pending = db.prepare(`SELECT count(*) FROM pairing_request WHERE status = 'pending'`).pluck().get();
    if (pending >= MAX_PENDING) throw new PosError("INVALID_STATE", "Too many devices are waiting to be paired. Try again in a few minutes.");
    const taken = db.prepare(`SELECT 1 FROM pairing_request WHERE status = 'pending' AND code = ?`).pluck();
    let code;
    do
      code = String(randomInt(0, 1e6)).padStart(6, "0");
    while (taken.get(code));
    const requestId = newId();
    const secret = randomBytes4(24).toString("base64url");
    const expiresAt = new Date(now.getTime() + PAIRING_MINUTES * 6e4).toISOString();
    db.prepare(
      `INSERT INTO pairing_request (id, code, secret_hash, device_name, kind, remote_addr, created_at, expires_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
    ).run(requestId, code, deviceTokenHash(secret), input2.name, input2.kind, remoteAddr, at, expiresAt);
    return { requestId, secret, code, expiresAt };
  }).immediate();
}
function pollPairingRequest(db, requestId, secret, now) {
  const at = now.toISOString();
  return db.transaction(() => {
    expireOld(db, at);
    const r = db.prepare("SELECT status, secret_hash, device_id FROM pairing_request WHERE id = ?").get(requestId);
    if (!r || r.secret_hash !== deviceTokenHash(secret)) throw new PosError("NOT_FOUND", "Unknown pairing request.");
    if (r.status === "pending") return { status: "pending" };
    if (r.status !== "approved" || !r.device_id) return { status: "expired" };
    const token = randomBytes4(32).toString("base64url");
    db.prepare("UPDATE device SET token_hash = ? WHERE id = ?").run(deviceTokenHash(token), r.device_id);
    db.prepare(`UPDATE pairing_request SET status = 'delivered' WHERE id = ?`).run(requestId);
    const name4 = db.prepare("SELECT name FROM device WHERE id = ?").pluck().get(r.device_id);
    return { status: "paired", deviceId: r.device_id, deviceName: name4, deviceToken: token };
  }).immediate();
}
function touchDevice(db, deviceId, now) {
  const at = now.toISOString();
  db.prepare(`UPDATE device SET last_seen_at = ? WHERE id = ? AND (last_seen_at IS NULL OR last_seen_at < ?)`).run(at, deviceId, new Date(now.getTime() - 6e4).toISOString());
}

// src/routes/licence.ts
function pairedCount(db, kind) {
  return db.prepare("SELECT count(*) FROM device WHERE kind = ? AND revoked_at IS NULL AND id <> ?").pluck().get(kind, MASTER_DEVICE_ID);
}
function seatsUsed(db) {
  const n2 = (kind) => pairedCount(db, kind);
  return { terminals: n2("terminal") + 1, captains: n2("captain"), kds: n2("kds") };
}
function licenceRoutes(app, deps) {
  app.get("/v1/licence", (_req, reply) => {
    const body2 = { ...deps.licence.status(deps.db, deps.now()), enforced: deps.licence.enforced, used: seatsUsed(deps.db) };
    void reply.header("cache-control", "no-store").send(body2);
    return reply;
  });
}

// src/commands/pair-device.ts
var SEAT_NAME = { terminal: "billing terminals", captain: "captain phones", kds: "kitchen screens" };
var SEAT_KEY = { terminal: "terminals", captain: "captains", kds: "kds" };
function refuseOverSeats(ctx, kind) {
  const seats = ctx.licence.seats(ctx.db, ctx.now);
  if (!seats) return;
  const paired = pairedCount(ctx.db, kind);
  const master = kind === "terminal" && !ctx.hosted ? 1 : 0;
  const used = paired + master;
  const allowed = seats[SEAT_KEY[kind]];
  if (used >= allowed) {
    throw new PosError("INVALID_STATE", `The licence allows ${allowed} ${SEAT_NAME[kind]}${master ? " (the master PC included)" : ""} and all are in use. Revoke one in Settings \u203A Devices, or ask for more seats.`, {
      reason: "seats",
      kind,
      allowed,
      used
    });
  }
}
var pairDevice = defineCommand({
  type: "PairDevice",
  schema: pairDeviceSchema,
  right: "admin",
  needsOrder: false,
  allowWhenDayClosed: true,
  apply(ctx, p) {
    const { db } = ctx;
    const req = db.prepare(`SELECT id, device_name, kind, remote_addr FROM pairing_request WHERE code = ? AND status = 'pending' AND expires_at > ?`).get(p.code, ctx.nowIso);
    if (!req) throw new PosError("NOT_FOUND", "No device is waiting with that code. Codes last 10 minutes; ask for a new one on the device.", { code: p.code });
    refuseOverSeats(ctx, req.kind);
    const approver = ctx.approve({ right: "admin" }, "Pairing a device needs a manager PIN.");
    const deviceId = newId();
    const name4 = p.name ?? req.device_name;
    db.prepare("INSERT INTO device (id, name, kind, paired_at) VALUES (?, ?, ?, ?)").run(deviceId, name4, req.kind, ctx.nowIso);
    db.prepare(`UPDATE pairing_request SET status = 'approved', approved_by = ?, approved_at = ?, device_id = ? WHERE id = ?`).run(approver, ctx.nowIso, deviceId, req.id);
    ctx.audit({ entity: "device", entityId: deviceId, action: "device.pair", after: { name: name4, kind: req.kind, remoteAddr: req.remote_addr } });
    ctx.emit("system", "device.paired", { deviceId, name: name4 });
    return { result: { deviceId, name: name4, kind: req.kind } };
  }
});

