// src/commands/reprint-bill.ts
var reprintBill = defineCommand({
  type: "ReprintBill",
  schema: reprintBillSchema,
  right: "reprint",
  needsOrder: false,
  allowWhenDayClosed: true,
  apply(ctx, p) {
    const { db } = ctx;
    const bill = db.prepare("SELECT id, state FROM bill WHERE id = ?").get(p.billId);
    if (!bill) throw new PosError("NOT_FOUND", "That bill does not exist.", { billId: p.billId });
    if (bill.state === "superseded") throw new PosError("INVALID_STATE", "Items changed after this bill was printed. Print the bill again (F9).", { state: bill.state });
    if (bill.state === "void") throw new PosError("INVALID_STATE", "This bill is void.", { state: bill.state });
    const doc = db.prepare("SELECT doc_json, bill_no_text FROM bill_document WHERE bill_id = ? ORDER BY revision DESC LIMIT 1").get(bill.id);
    if (!doc) throw new PosError("INVALID_STATE", "This bill has no stored copy to reprint.", { billId: bill.id });
    const cfg = getConfig(db);
    const printer = billPrinter(db, cfg);
    if (!printer) throw new PosError("INVALID_STATE", "No bill printer is set up. Add one in Settings, Kitchen & printers.");
    const { bytes, preview } = renderBill({ ...JSON.parse(doc.doc_json), duplicate: true }, { paper: printer.paper, logo: billLogoBits(cfg) });
    ctx.print({ printerId: printer.id, docKind: "bill", refId: bill.id, bytes, previewText: preview });
    const reprint = db.prepare("SELECT count(*) FROM audit_event WHERE entity_id = ? AND action = 'bill.reprint'").pluck().get(bill.id) + 1;
    ctx.audit({ entity: "bill", entityId: bill.id, action: "bill.reprint", after: { billNo: doc.bill_no_text, reprint }, leakage: true });
    return { result: { billId: bill.id, billNo: doc.bill_no_text, reprint } };
  }
});

// src/commands/request-bill.ts
var requestBill = defineCommand({
  type: "RequestBill",
  schema: requestBillSchema,
  right: "order.edit",
  needsOrder: true,
  apply(ctx, _p, order) {
    const o = order;
    const { db } = ctx;
    if (o.state === "billed") throw new PosError("INVALID_STATE", "The bill is already printed.", { state: o.state });
    if (o.state !== "open") throw new PosError("INVALID_STATE", `This order is ${o.state}; it can no longer be billed.`, { state: o.state });
    if (!db.prepare("SELECT 1 FROM order_item WHERE order_id = ? AND status = 'fired' LIMIT 1").get(o.id)) {
      throw new PosError("INVALID_STATE", "Nothing has been sent to the kitchen yet.");
    }
    const before = db.prepare("SELECT requested_at FROM bill_request WHERE order_id = ?").pluck().get(o.id);
    db.prepare(
      `INSERT INTO bill_request (order_id, requested_at, requested_by) VALUES (?, ?, ?)
       ON CONFLICT (order_id) DO UPDATE SET requested_at = excluded.requested_at, requested_by = excluded.requested_by`
    ).run(o.id, ctx.nowIso, ctx.actor.userId);
    const table = o.table_id ? db.prepare("SELECT label FROM dining_table WHERE id = ?").pluck().get(o.table_id) : void 0;
    const byName = ctx.actor.userId ? db.prepare("SELECT name FROM app_user WHERE id = ?").pluck().get(ctx.actor.userId) : void 0;
    ctx.audit({ entity: "order", entityId: o.id, action: "order.bill_request", before: before ? { requestedAt: before } : null, after: { requestedAt: ctx.nowIso } });
    ctx.emit("floor", "bill.requested", { orderId: o.id, tableId: o.table_id, tableLabel: table ?? null, byName: byName ?? null, at: ctx.nowIso });
    emitTableState(ctx, o.table_id);
    return { result: { requestedAt: ctx.nowIso } };
  }
});

