// src/commands/revoke-device.ts
var revokeDevice = defineCommand({
  type: "RevokeDevice",
  schema: revokeDeviceSchema,
  right: "admin",
  needsOrder: false,
  allowWhenDayClosed: true,
  apply(ctx, p) {
    const { db } = ctx;
    if (p.deviceId === MASTER_DEVICE_ID) throw new PosError("INVALID_STATE", "The master PC cannot be revoked; it is the server itself.");
    const d = db.prepare("SELECT name, revoked_at FROM device WHERE id = ?").get(p.deviceId);
    if (!d) throw new PosError("NOT_FOUND", "That device does not exist.", { deviceId: p.deviceId });
    if (d.revoked_at) throw new PosError("INVALID_STATE", `${d.name} is already revoked.`);
    if (ctx.actor.deviceId === p.deviceId) throw new PosError("INVALID_STATE", "A device cannot revoke itself. Do it from another terminal.");
    db.prepare("UPDATE device SET revoked_at = ?, token_hash = NULL WHERE id = ?").run(ctx.nowIso, p.deviceId);
    const ended = db.prepare("DELETE FROM user_session WHERE device_id = ?").run(p.deviceId).changes;
    ctx.audit({ entity: "device", entityId: p.deviceId, action: "device.revoke", before: { name: d.name }, after: { revoked: true, sessionsEnded: ended } });
    ctx.emit("system", "device.revoked", { deviceId: p.deviceId });
    return { result: { deviceId: p.deviceId, sessionsEnded: ended } };
  }
});

// src/commands/update-held-item.ts
function requireHeldItem(ctx, orderId, orderItemId) {
  const row = ctx.db.prepare("SELECT * FROM order_item WHERE id = ? AND order_id = ?").get(orderItemId, orderId);
  if (!row) throw new PosError("NOT_FOUND", "That item is not on this order.", { orderItemId });
  if (row.status !== "held") {
    throw new PosError("INVALID_STATE", `${row.name_snapshot} was already sent to the kitchen; use modify or cancel instead.`, {
      orderItemId,
      status: row.status
    });
  }
  return row;
}
var updateHeldItem = defineCommand({
  type: "UpdateHeldItem",
  schema: updateHeldItemSchema,
  right: "order.edit",
  needsOrder: true,
  apply(ctx, p, order) {
    const o = order;
    requireEditable(o);
    const before = requireHeldItem(ctx, o.id, p.orderItemId);
    const beforeAddons = ctx.db.prepare("SELECT addon_id, qty FROM order_item_addon WHERE order_item_id = ?").all(p.orderItemId);
    const qty3 = p.qty ?? before.qty;
    const note3 = p.note === void 0 ? before.note : p.note;
    const course2 = p.course ?? before.course;
    ctx.db.prepare("UPDATE order_item SET qty = ?, note = ?, course = ? WHERE id = ?").run(qty3, note3, course2, p.orderItemId);
    if (p.addons) writeAddons(ctx.db, p.orderItemId, priceAddons(ctx.db, before.item_id, p.addons));
    ctx.audit({
      entity: "order_item",
      entityId: p.orderItemId,
      action: "order.item.update",
      before: { qty: before.qty, note: before.note, course: before.course, addons: beforeAddons },
      after: { qty: qty3, note: note3, course: course2, ...p.addons ? { addons: p.addons } : {} }
    });
    emitTableState(ctx, o.table_id);
    return { result: { orderItemId: p.orderItemId } };
  }
});

