// src/commands/set-config.ts
var setConfig = defineCommand({
  type: "SetConfig",
  schema: setConfigSchema,
  right: "admin",
  needsOrder: false,
  allowWhenDayClosed: true,
  apply(ctx, p) {
    const values = p.values;
    if (values["bill.printerId"]) requireRef(ctx.db, "printer", values["bill.printerId"], "bill.printerId");
    if (values["kot.default_station_id"]) requireRef(ctx.db, "station", values["kot.default_station_id"], "kot.default_station_id");
    const before = getConfig(ctx.db);
    const changed = {};
    for (const [key, value] of Object.entries(values)) {
      if (JSON.stringify(before[key]) === JSON.stringify(value)) continue;
      setConfigValue(ctx.db, key, value);
      changed[key] = value;
      ctx.audit({ entity: "config", entityId: key, action: "config.set", before: { value: before[key] }, after: { value } });
    }
    if (Object.keys(changed).length > 0) ctx.emit("system", "config.changed", { keys: Object.keys(changed) });
    return { result: { changed: Object.keys(changed) } };
  }
});

