// src/commands/transfer-items.ts
var transferItems = defineCommand({
  type: "TransferItems",
  schema: transferItemsSchema,
  right: "item.transfer",
  needsOrder: true,
  apply(ctx, p, order) {
    const from = order;
    requireLive(from, "This order");
    if (p.toOrderId === from.id) throw new PosError("INVALID_STATE", "Choose another table to move the items to.", { orderId: from.id });
    const to = loadOrder(ctx, p.toOrderId);
    requireLive(to, `The order on ${tableLabel(ctx, to.table_id)}`);
    const { db } = ctx;
    const rows = db.prepare(`SELECT id, status, station_id, qty, name_snapshot AS name, course, note FROM order_item WHERE order_id = ? AND id IN (SELECT value FROM json_each(?))`).all(from.id, JSON.stringify(p.itemIds));
    if (rows.length !== p.itemIds.length) {
      const missing = p.itemIds.filter((id) => !rows.some((r) => r.id === id));
      throw new PosError("NOT_FOUND", "Some items are not on this order.", { orderItemIds: missing });
    }
    const cancelled = rows.filter((r) => r.status === "cancelled");
    if (cancelled.length) throw new PosError("INVALID_STATE", "Cancelled items cannot be moved.", { orderItemIds: cancelled.map((r) => r.id) });
    reopenIfBilled(ctx, from);
    touchOther(ctx, to);
    const move = db.prepare("UPDATE order_item SET original_order_id = coalesce(original_order_id, order_id), order_id = ? WHERE id = ?");
    for (const r of rows) move.run(to.id, r.id);
    const fired = rows.filter((r) => r.status === "fired");
    const fromLabel = tableLabel(ctx, from.table_id);
    const toLabel = tableLabel(ctx, to.table_id);
    const notices = sendMoveNotices(ctx, loadOrder(ctx, to.id), fired, `ITEMS ${fromLabel} -> ${toLabel}`, true);
    ctx.audit({
      entity: "order",
      entityId: from.id,
      action: "order.transfer_items",
      before: { table: fromLabel },
      after: { toOrderId: to.id, table: toLabel, items: rows.map((r) => ({ id: r.id, name: r.name, qty: r.qty, status: r.status })), noticeKotNos: notices },
      leakage: fired.length > 0
    });
    emitTableState(ctx, from.table_id);
    emitTableState(ctx, to.table_id);
    return { result: { toOrderId: to.id, moved: rows.length, noticeKotNos: notices } };
  }
});

// src/commands/split-bill.ts
var splitBill = defineCommand({
  type: "SplitBill",
  schema: splitBillSchema,
  right: "bill.split",
  needsOrder: true,
  apply(ctx, p, order) {
    const o = order;
    const { db } = ctx;
    if (o.state !== "billed") throw new PosError("INVALID_STATE", o.state === "open" ? "Print the bill first (F9), then split it." : `This order is ${o.state}.`, { state: o.state });
    const paid = db.prepare(`SELECT count(*) FROM bill b WHERE b.order_id = ? AND (b.state = 'settled' OR EXISTS (SELECT 1 FROM payment p WHERE p.bill_id = b.id))`).pluck().get(o.id);
    if (paid > 0) throw new PosError("INVALID_STATE", "Part of this bill is already paid; it can no longer be split.");
    const printed = db.prepare(`SELECT * FROM bill WHERE order_id = ? AND state = 'printed' ORDER BY fy, bill_no, split_no`).all(o.id);
    if (printed.length === 0) throw new PosError("INVALID_STATE", "Print the bill first (F9), then split it.");
    const firstDoc = JSON.parse(db.prepare("SELECT doc_json FROM bill_document WHERE bill_id = ? ORDER BY revision DESC LIMIT 1").pluck().get(printed[0].id));
    const cfg = getConfig(db);
    const place = orderPlace(db, o);
    const { items: items2 } = billableItems(db, o.id);
    const discountPaise = sumPaise(printed.map((b) => b.discount_paise));
    const serviceChargeBp = firstDoc.serviceChargeBp ?? 0;
    const whole = calculateBill(toBillLines(items2), {
      pricingMode: place.pricingMode,
      interState: false,
      discount: discountPaise > 0 ? { kind: "amount", valuePaise: discountPaise } : null,
      serviceChargeBp,
      roundOffStep: cfg["bill.roundOffStep"],
      roundOffTie: cfg["bill.roundOffTie"]
    });
    if (whole.total !== sumPaise(printed.map((b) => b.total_paise))) {
      throw new PosError("INVALID_STATE", "The order changed since the bill was printed. Print the bill again (F9).");
    }
    let weights;
    let labels;
    const n2 = p.mode === "equal" ? p.parts : p.parts.length;
    if (p.mode === "equal") {
      weights = equalWeights(items2.length, n2);
      labels = items2.map(() => weights[0].map(() => `1/${n2}`));
    } else if (p.mode === "proportion") {
      const w = p.parts.map((x) => x.weight);
      const sum = w.reduce((a, b) => a + b, 0);
      weights = proportionWeights(items2.length, w);
      labels = items2.map(() => w.map((x) => `${x}/${sum}`));
    } else {
      const index = new Map(items2.map((it, i) => [it.id, i]));
      weights = items2.map(() => p.parts.map(() => 0));
      p.parts.forEach((part, k) => {
        for (const a of part.items) {
          const i = index.get(a.orderItemId);
          if (i === void 0) throw new PosError("NOT_FOUND", "That item is not on this bill.", { orderItemId: a.orderItemId });
          weights[i][k] += a.qty;
        }
      });
      const wrong = items2.filter((it, i) => weights[i].reduce((a, b) => a + b, 0) !== it.qty);
      if (wrong.length) {
        throw new PosError("VALIDATION", `Assign every item exactly once: ${wrong.map((w) => w.name).join(", ")}.`, { orderItemIds: wrong.map((w) => w.id) });
      }
      if (p.parts.some((_, k) => weights.every((row) => row[k] === 0))) throw new PosError("VALIDATION", "Every part needs at least one item.");
      labels = items2.map((it, i) => weights[i].map((q) => q === it.qty ? null : `${q}/${it.qty}`));
    }
    const parts = splitBreakup(whole, weights, cfg["bill.roundOffStep"]);
    const when = printedDateTime(ctx.now, ctx.timeZone);
    const printer = billPrinter(db, cfg);
    const logo = billLogoBits(cfg);
    const out = [];
    const insertDoc = db.prepare("INSERT INTO bill_document (bill_id, revision, bill_no_text, doc_json, created_at, command_id) VALUES (?, ?, ?, ?, ?, ?)");
    parts.forEach((b, k) => {
      const amounts = [b.subtotal, b.discount, printed[0].discount_reason, b.serviceCharge, b.cgst, b.sgst, b.igst, b.roundOff, b.total, printed[0].customer_gstin];
      const reuse = printed[k];
      let billId;
      let billNoText;
      let revision;
      if (reuse) {
        billId = reuse.id;
        const last = db.prepare("SELECT bill_no_text, revision FROM bill_document WHERE bill_id = ? ORDER BY revision DESC LIMIT 1").get(billId);
        billNoText = last.bill_no_text;
        revision = last.revision + 1;
        db.prepare(
          `UPDATE bill SET subtotal_paise = ?, discount_paise = ?, discount_reason = ?, service_charge_paise = ?, cgst_paise = ?, sgst_paise = ?, igst_paise = ?,
                  round_off_paise = ?, total_paise = ?, customer_gstin = ?, split_of = ?, printed_at = ?, print_count = print_count + 1 WHERE id = ?`
        ).run(...amounts, n2, ctx.nowIso, billId);
      } else {
        billId = newId();
        const fy = financialYearAt(ctx.now, ctx.timeZone);
        const seq = nextCounter(db, `bill_no:${fy}`);
        billNoText = formatBillNo(cfg["bill.prefix"], fy, seq);
        revision = 1;
        db.prepare(
          `INSERT INTO bill (id, order_id, fy, bill_no, split_no, split_of, subtotal_paise, discount_paise, discount_reason, service_charge_paise, cgst_paise,
                             sgst_paise, igst_paise, round_off_paise, total_paise, customer_gstin, printed_at, print_count, state)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, 'printed')`
        ).run(billId, o.id, fy, seq, k + 1, n2, ...amounts, ctx.nowIso);
      }
      const lines = [];
      items2.forEach((it, i) => {
        const share2 = b.lines.find((l) => l.id === it.id);
        if (!share2) return;
        const label = labels[i][k];
        lines.push(
          label ? { name: it.name, qty: it.qty, qtyText: label, unitPricePaise: whole.lines[i].amount, amountPaise: share2.amount } : {
            name: it.name,
            qty: it.qty,
            unitPricePaise: it.unitPricePaise,
            amountPaise: it.unitPricePaise * it.qty,
            addons: it.addons.map((a) => ({ name: a.name, qty: a.qty, amountPaise: a.pricePaise * a.qty }))
          }
        );
      });
      const doc = {
        ...firstDoc,
        outlet: billOutlet(cfg),
        billNo: billNoText,
        date: when.date,
        time: when.time,
        cashierName: userName(db, ctx.actor.userId),
        lines,
        breakup: b,
        part: { no: k + 1, of: n2 },
        duplicate: false,
        display: cfg["bill.display"]
      };
      insertDoc.run(billId, revision, billNoText, JSON.stringify(doc), ctx.nowIso, ctx.commandId);
      if (printer) {
        const { bytes, preview } = renderBill(doc, { paper: printer.paper, logo });
        ctx.print({ printerId: printer.id, docKind: "bill", refId: billId, bytes, previewText: preview });
      }
      out.push({ billId, billNo: billNoText, totalPaise: b.total });
    });
    const voided = printed.slice(n2).map((b) => b.id);
    for (const id of voided) {
      db.prepare(`UPDATE bill SET state = 'void' WHERE id = ?`).run(id);
      ctx.audit({ entity: "bill", entityId: id, action: "bill.void", before: { state: "printed" }, after: { state: "void" }, reason: "Not needed after re-splitting the bill" });
    }
    ctx.audit({ entity: "order", entityId: o.id, action: "bill.split", after: { mode: p.mode, parts: out, voided, wholeTotalPaise: whole.total } });
    emitTableState(ctx, o.table_id);
    return { result: { bills: out, ...printer ? {} : { warning: "No bill printer is set up; the parts were saved but not printed." } } };
  }
});

// src/commands/update-reservation.ts
var updateReservation = defineCommand({
  type: "UpdateReservation",
  schema: updateReservationSchema,
  right: "reservation.manage",
  needsOrder: false,
  apply(ctx, p) {
    const r = requireReservation(ctx, p.reservationId);
    requireBooked(r);
    const beforeTables = tablesOf(ctx.db, r.id);
    const next = {
      guestName: p.guestName ?? r.guest_name,
      phone: p.phone === void 0 ? r.phone : p.phone,
      partySize: p.partySize ?? r.party_size,
      startsAt: p.startsAt ? new Date(p.startsAt).toISOString() : r.starts_at,
      durationMin: p.durationMin ?? r.duration_min,
      note: p.note === void 0 ? r.note : p.note,
      tableIds: p.tableIds ?? beforeTables
    };
    if (p.startsAt && Date.parse(next.startsAt) < ctx.now.getTime() - PAST_GRACE_MS) throw new PosError("VALIDATION", "That time has already passed.", { field: "startsAt" });
    requireBookableTables(ctx, next.tableIds);
    refuseClashes(ctx, next.tableIds, next.startsAt, next.durationMin, r.id);
    ctx.db.prepare("UPDATE reservation SET guest_name = ?, phone = ?, party_size = ?, starts_at = ?, duration_min = ?, note = ? WHERE id = ?").run(next.guestName, next.phone, next.partySize, next.startsAt, next.durationMin, next.note, r.id);
    if (p.tableIds) {
      ctx.db.prepare("DELETE FROM reservation_table WHERE reservation_id = ?").run(r.id);
      const link = ctx.db.prepare("INSERT INTO reservation_table (reservation_id, table_id) VALUES (?, ?)");
      for (const t of p.tableIds) link.run(r.id, t);
    }
    ctx.audit({
      entity: "reservation",
      entityId: r.id,
      action: "reservation.update",
      before: { guestName: r.guest_name, phone: r.phone, partySize: r.party_size, startsAt: r.starts_at, durationMin: r.duration_min, note: r.note, tableIds: beforeTables },
      after: next
    });
    bookingsChanged(ctx, { reservationId: r.id });
    return { result: { reservationId: r.id } };
  }
});

// src/commands/upsert-addon-group.ts
var upsertAddonGroup = defineCommand({
  type: "UpsertAddonGroup",
  schema: upsertAddonGroupSchema,
  right: "admin",
  needsOrder: false,
  allowWhenDayClosed: true,
  apply(ctx, p) {
    const ownerOf = ctx.db.prepare("SELECT group_id FROM addon WHERE id = ?").pluck();
    const ids = /* @__PURE__ */ new Set();
    for (const a of p.addons) {
      if (ids.has(a.id)) throw new PosError("VALIDATION", "An addon is listed twice.", { addonId: a.id });
      ids.add(a.id);
      const owner = ownerOf.get(a.id);
      if (owner !== void 0 && owner !== p.id) {
        throw new PosError("INVALID_STATE", `Addon ${a.name} belongs to another group.`, { addonId: a.id, groupId: owner });
      }
    }
    const row = { id: p.id, name: p.name, min_select: p.minSelect, max_select: p.maxSelect };
    const before = upsertById(ctx.db, "addon_group", row);
    for (const a of p.addons) upsertById(ctx.db, "addon", { id: a.id, group_id: p.id, name: a.name, price_paise: a.pricePaise });
    auditUpsert(ctx, "addon_group", p.id, before, { ...row, addons: p.addons });
    menuChanged(ctx);
    return { result: { id: p.id, created: !before } };
  }
});

