// src/commands/upsert-role.ts
var upsertRole = defineCommand({
  type: "UpsertRole",
  schema: upsertRoleSchema,
  right: "users.manage",
  needsOrder: false,
  allowWhenDayClosed: true,
  apply(ctx, p) {
    const { db } = ctx;
    if (p.id === OWNER_ROLE_ID && !p.rights.some((r) => r.right === "users.manage" && !r.needsPin)) {
      throw new PosError("INVALID_STATE", 'The Owner role must keep "Manage staff, PINs and roles" without a PIN.');
    }
    const clash = db.prepare("SELECT 1 FROM role WHERE name = ? COLLATE NOCASE AND id <> ?").get(p.name, p.id);
    if (clash) throw new PosError("INVALID_STATE", `A role called ${p.name} already exists.`);
    const before = db.prepare("SELECT name, discount_limit_bp FROM role WHERE id = ?").get(p.id);
    const beforeRights = before ? roleRights(db, p.id) : [];
    db.prepare(
      "INSERT INTO role (id, name, discount_limit_bp) VALUES (?, ?, ?) ON CONFLICT(id) DO UPDATE SET name = excluded.name, discount_limit_bp = excluded.discount_limit_bp"
    ).run(p.id, p.name, p.discountLimitBp);
    db.prepare("DELETE FROM role_permission WHERE role_id = ?").run(p.id);
    const ins = db.prepare("INSERT INTO role_permission (role_id, permission, needs_pin) VALUES (?, ?, ?)");
    for (const r of p.rights) ins.run(p.id, r.right, r.needsPin ? 1 : 0);
    ctx.audit({
      entity: "role",
      entityId: p.id,
      action: before ? "role.update" : "role.create",
      before: before ? { name: before.name, discountLimitBp: before.discount_limit_bp, rights: beforeRights } : void 0,
      after: { name: p.name, discountLimitBp: p.discountLimitBp, rights: p.rights }
    });
    ctx.emit("system", "staff.changed", { roleId: p.id });
    return { result: { id: p.id, created: !before } };
  }
});

// src/commands/upsert-user.ts
function managersAfter(db, change) {
  const rows = db.prepare(
    `SELECT u.id, u.role_id, u.active FROM app_user u
       JOIN role_permission p ON p.role_id = u.role_id AND p.permission = 'users.manage' AND p.needs_pin = 0`
  ).all();
  const canManage = db.prepare(`SELECT 1 FROM role_permission WHERE role_id = ? AND permission = 'users.manage' AND needs_pin = 0`).get(change.roleId) !== void 0;
  const others = rows.filter((r) => r.id !== change.id && r.active === 1).length;
  return others + (change.active && canManage ? 1 : 0);
}
var upsertUser = defineCommand({
  type: "UpsertUser",
  schema: upsertUserSchema,
  right: "users.manage",
  needsOrder: false,
  allowWhenDayClosed: true,
  apply(ctx, p) {
    const { db } = ctx;
    requireRef(db, "role", p.roleId, "roleId");
    const before = db.prepare("SELECT id, name, role_id, pin_hash, active FROM app_user WHERE id = ?").get(p.id);
    if (!before && !p.pin) throw new PosError("VALIDATION", "A new person needs a PIN.", [{ path: "pin", message: "required for a new person" }]);
    if (p.active) {
      const clash = db.prepare("SELECT 1 FROM app_user WHERE active = 1 AND name = ? COLLATE NOCASE AND id <> ?").get(p.name, p.id);
      if (clash) throw new PosError("INVALID_STATE", `Someone called ${p.name} is already on the staff list. Add a surname or initial.`);
    }
    if (p.pin) {
      const others = db.prepare("SELECT pin_hash FROM app_user WHERE id <> ? AND active = 1").pluck().all(p.id);
      if (others.some((h) => verifyPin(p.pin, h))) throw new PosError("INVALID_STATE", "Another person already uses this PIN. Choose a different one.");
    }
    if (before && ctx.actor.userId === p.id && (!p.active || p.roleId !== before.role_id)) {
      throw new PosError("INVALID_STATE", "You cannot deactivate yourself or change your own role. Ask another owner.");
    }
    if (managersAfter(db, { id: p.id, roleId: p.roleId, active: p.active }) === 0) {
      throw new PosError("INVALID_STATE", "At least one active person must be able to manage staff.");
    }
    const pinHash = p.pin ? hashPin(p.pin) : before.pin_hash;
    if (before) {
      db.prepare("UPDATE app_user SET name = ?, role_id = ?, pin_hash = ?, active = ?" + (p.pin ? ", failed_attempts = 0, locked_until = NULL" : "") + " WHERE id = ?").run(
        p.name,
        p.roleId,
        pinHash,
        p.active ? 1 : 0,
        p.id
      );
      if (p.pin || !p.active || p.roleId !== before.role_id) endSessionsOf(db, p.id);
    } else {
      db.prepare("INSERT INTO app_user (id, name, role_id, pin_hash, active) VALUES (?, ?, ?, ?, ?)").run(p.id, p.name, p.roleId, pinHash, p.active ? 1 : 0);
    }
    ctx.audit({
      entity: "user",
      entityId: p.id,
      action: before ? "user.update" : "user.create",
      // Never the PIN or its hash.
      before: before ? { name: before.name, roleId: before.role_id, active: before.active === 1 } : void 0,
      after: { name: p.name, roleId: p.roleId, active: p.active, pinChanged: Boolean(p.pin) }
    });
    ctx.emit("system", "staff.changed", { userId: p.id });
    return { result: { id: p.id, created: !before } };
  }
});

