// src/queries/kds.ts
function getKdsBoard(db, stationId, now, timeZone) {
  const station = db.prepare("SELECT id, name FROM station WHERE id = ?").get(stationId);
  if (!station) throw new PosError("NOT_FOUND", "Kitchen station not found.", { stationId });
  const config2 = getConfig(db);
  const day = currentBusinessDate(db);
  const rows = day ? db.prepare(
    `SELECT k.id, k.order_id, k.kot_no, k.kind, k.fired_at, k.ready_at, d.ticket_json
           FROM kot k JOIN kot_document d ON d.kot_id = k.id JOIN "order" o ON o.id = k.order_id
           WHERE k.station_id = ? AND k.business_date = ? AND k.served_at IS NULL AND o.state NOT IN ('settled', 'void')
           ORDER BY k.fired_at, k.kot_no`
  ).all(station.id, day) : [];
  const tickets = rows.map((r) => {
    const t = JSON.parse(r.ticket_json);
    return {
      id: r.id,
      kotNo: r.kot_no,
      kind: r.kind,
      orderId: r.order_id,
      orderType: t.orderType,
      tableLabel: t.tableLabel ?? null,
      areaName: t.areaName ?? null,
      covers: t.covers ?? null,
      captainName: t.captainName ?? null,
      firedAt: r.fired_at,
      ...r.ready_at ? { readyAt: r.ready_at } : {},
      lines: t.lines,
      forKotNo: t.forKotNo ?? null,
      reason: t.reason ?? null,
      notice: t.notice ?? null
    };
  });
  const amberMin = config2["kds.amberMin"];
  const today = day ? stationDay(db, station.id, day, amberMin) : { served: 0, bumped: 0, avgReadySec: null, late: 0 };
  return { serverTime: isoInZone(now, timeZone), station, amberMin, redMin: Math.max(config2["kds.redMin"], amberMin + 1), tickets, today };
}
function stationDay(db, stationId, day, amberMin) {
  const r = db.prepare(
    `SELECT sum(CASE WHEN served_at IS NOT NULL THEN 1 ELSE 0 END) AS served,
              sum(CASE WHEN ready_at IS NOT NULL THEN 1 ELSE 0 END) AS bumped,
              avg(CASE WHEN ready_at IS NOT NULL THEN (julianday(ready_at) - julianday(fired_at)) * 86400 END) AS avgSec,
              sum(CASE WHEN ready_at IS NOT NULL AND round((julianday(ready_at) - julianday(fired_at)) * 86400) > ? * 60 THEN 1 ELSE 0 END) AS late
       FROM kot WHERE station_id = ? AND business_date = ? AND kind = 'new'`
  ).get(amberMin, stationId, day);
  return { served: r.served ?? 0, bumped: r.bumped ?? 0, avgReadySec: r.avgSec === null ? null : Math.round(r.avgSec), late: r.late ?? 0 };
}

// src/queries/printers.ts
function getPrinters(db, liveStatus, now = /* @__PURE__ */ new Date(), liveError) {
  const rows = db.prepare("SELECT id, name, transport, role, width_mm, backup_printer_id FROM printer ORDER BY name COLLATE NOCASE").all();
  const pending = db.prepare(`SELECT count(*) FROM print_job WHERE printer_id = ? AND state IN ('queued', 'retry')`).pluck();
  const retrying = db.prepare(`SELECT 1 FROM print_job WHERE printer_id = ? AND state = 'retry' LIMIT 1`).pluck();
  const last = db.prepare(`SELECT state, last_error FROM print_job WHERE printer_id = ? AND state IN ('done', 'failed') ORDER BY done_at DESC, rowid DESC LIMIT 1`);
  const agentOf = db.prepare("SELECT a.id, a.name FROM printer_agent pa JOIN print_agent a ON a.id = pa.agent_id WHERE pa.printer_id = ? AND a.revoked_at IS NULL");
  const failedToday = db.prepare(`SELECT count(*) FROM print_job WHERE printer_id = ? AND state = 'failed' AND created_at >= ?`).pluck();
  const dayStart = new Date(now.getTime() - 24 * 36e5).toISOString();
  return rows.map((r) => {
    const lastRow = last.get(r.id);
    const derived2 = retrying.get(r.id) ? "retrying" : lastRow?.state === "failed" ? "offline" : "ok";
    const live = liveStatus?.(r.id);
    const lastError = live ? live === "ok" ? null : liveError?.(r.id) ?? (lastRow?.state === "failed" ? lastRow.last_error : null) : lastRow?.state === "failed" ? lastRow.last_error : null;
    return {
      id: r.id,
      name: r.name,
      transport: r.transport,
      role: r.role,
      widthMm: r.width_mm,
      ...r.backup_printer_id ? { backupPrinterId: r.backup_printer_id } : {},
      status: live ?? derived2,
      queued: pending.get(r.id),
      failedToday: failedToday.get(r.id, dayStart),
      ...lastError ? { lastError } : {},
      ...(() => {
        const a = agentOf.get(r.id);
        return a ? { agent: a } : {};
      })()
    };
  });
}

