// src/reports/catalog.ts
var n = (v) => Number(v ?? 0);
var all = (c, sql, ...args) => c.db.prepare(sql).all(...args);
var IN_RANGE = "o.business_date BETWEEN @from AND @to";
var params = (c) => ({ from: c.from, to: c.to });
var BILL_NO = `(SELECT d.bill_no_text FROM bill_document d WHERE d.bill_id = b.id ORDER BY d.revision DESC LIMIT 1)`;
var TABLE = `COALESCE((SELECT t.label FROM dining_table t WHERE t.id = o.table_id), 'Takeaway')`;
var rate = (bp) => `${Math.trunc(bp / 100)}${bp % 100 ? `.${String(bp % 100).padStart(2, "0").replace(/0$/, "")}` : ""}%`;
